import json, csv, re, collections
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
tmap = {}
issues = []
for t in tr:
    m = re.findall(r'FINAL SCORE:\s*(\S+)', t['judge_output'])
    dl = re.search(r'Displayed author: (\S+?)\.', t['judge_output'])
    tmap[t['rating_id']] = (m, dl.group(1) if dl else None, t)
    if t['judge_model'] != 'atlas-7': issues.append(('judge', t['rating_id'], t['judge_model']))
    if dl and dl.group(1) != t['displayed_label']: issues.append(('label_mismatch', t['rating_id'], dl.group(1), t['displayed_label']))
    if len(m) != 1: issues.append(('score_count', t['rating_id'], m))
for r in rows:
    m, dl, t = tmap.get(r['rating_id'], (None,None,None))
    if t is None: issues.append(('missing', r['rating_id'])); continue
    if m and m[0] != r['score']: issues.append(('score_diff', r['rating_id'], m[0], r['score']))
    if t['response_id'] != r['response_id'] or t['session'] != int(r['session']) or t['displayed_label'] != r['displayed_label']:
        issues.append(('meta_diff', r['rating_id']))
print(issues)
# pairing structure
by = collections.defaultdict(list)
for r in rows: by[r['response_id']].append(r)
print(collections.Counter(len(v) for v in by.values()))
for k,v in by.items():
    labs = sorted((x['session'], x['displayed_label']) for x in v)
    if labs != [('1','atlas-7'),('2','nova-3')] and labs != [('1','nova-3'),('2','atlas-7')]:
        print('odd', k, labs)
print(collections.Counter(r['session']+r['displayed_label'] for r in rows))
# session-level check: do session 1 and 2 labels line up with the randomisation? 
print(collections.Counter((r['session'],r['displayed_label']) for r in rows))
